export type Copy=typeof copy.en;
const C=createContext<{lang:Lang;t:Copy;setLang:(x:Lang)=>void}>({lang:'en',t:copy.en,setLang:()=>{}});
export function I18nProvider({children}:{children:ReactNode}){const [lang,setLang]=useState<Lang>(()=>(localStorage.getItem('boldtrace.lang') as Lang)||'en');const value=useMemo(()=>{localStorage.setItem('boldtrace.lang',lang);document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';return{lang,t:copy[lang],setLang}},[lang]);return <C.Provider value={value}>{children}</C.Provider>}
export const useI18n=()=>useContext(C);
